export function WebPaneStack({
  views,
  root,
  active,
  activeId,
  focused,
  onToggleFocus,
  onTitle,
  onBlockedNavigation,
  onOpenBrowser,
  onRevealTerminal,
}: {
  readonly views: readonly WebViewState[]
  readonly root: HostPath
